module sync_fifo #(parameter DATA_WIDTH = 8, parameter DEPTH = 16, parameter ADDR_WIDTH = 4) (
    input wire clk,
    input wire rst_n,
    input wire wr_valid,
    output wire wr_ready,
    input wire [DATA_WIDTH-1:0] wr_data,
    output wire rd_valid,
    input wire rd_ready,
    output wire [DATA_WIDTH-1:0] rd_data
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
    reg [ADDR_WIDTH-1:0] wr_ptr;
    reg [ADDR_WIDTH-1:0] rd_ptr;
    reg [ADDR_WIDTH:0]   occupancy;
    reg [DATA_WIDTH-1:0] fifo_mem [0:DEPTH-1];

    // Full level expressed in the occupancy width (ADDR_WIDTH+1 bits).
    localparam [ADDR_WIDTH:0] FULL_LEVEL = DEPTH[ADDR_WIDTH:0];

    // Flow-control status derived from occupancy (control_flow: wr_ready_gate, rd_valid_gate).
    assign wr_ready = (occupancy < FULL_LEVEL);
    assign rd_valid = (occupancy != {(ADDR_WIDTH+1){1'b0}});

    // Registered pointer storage read (data_flow: read_path).
    assign rd_data  = fifo_mem[rd_ptr];

    // Handshake fire terms (control_flow: write_accept, read_accept).
    wire wr_fire = wr_valid & wr_ready;
    wire rd_fire = rd_valid & rd_ready;

    always @(posedge clk) begin
      if (!rst_n) begin
        // control_flow: reset_state
        wr_ptr    <= {ADR_WIDTH{1'b0}};
        rd_ptr    <= {ADDR_WIDTH{1'b0}};
        occupancy <= {(ADDR_WIDTH+1){1'b0}};
      end else begin
        // Write path store + write pointer advance (control_flow: write_accept, write_path).
        if (wr_fire) begin
          fifo_mem[wr_ptr] <= wr_data;
          wr_ptr <= wr_ptr + {{(ADDR_WIDTH-1){1'b0}}, 1'b1};
        end

        // Read pointer advance (control_flow: read_accept, read_path).
        if (rd_fire) begin
          rd_ptr <= rd_ptr + {{(ADDR_WIDTH-1){1'b0}}, 1'b1};
        end

        // Occupancy tracking (control_flow: occupancy_increment, occupancy_decrement).
        case ({wr_fire, rd_fire})
          2'b10:   occupancy <= occupancy + {{ADDR_WIDTH{1'b0}}, 1'b1};
          2'b01:   occupancy <= occupancy - {{ADDR_WIDTH{1'b0}}, 1'b1};
          default: occupancy <= occupancy;
        endcase
      end
    end
  // SR2FPGA_BEHAVIOR_END
endmodule

module top #(parameter DATA_WIDTH = 8, parameter DEPTH = 16, parameter ADDR_WIDTH = 4) (
    input wire clk,
    input wire rst_n,
    input wire wr_valid,
    output wire wr_ready,
    input wire [DATA_WIDTH-1:0] wr_data,
    output wire rd_valid,
    input wire rd_ready,
    output wire [DATA_WIDTH-1:0] rd_data
);

  wire u_fifo__wr_valid;
  wire u_fifo__wr_ready;
  wire [DATA_WIDTH-1:0] u_fifo__wr_data;
  wire u_fifo__rd_valid;
  wire u_fifo__rd_ready;
  wire [DATA_WIDTH-1:0] u_fifo__rd_data;

  assign u_fifo__wr_data = wr_data;
  assign u_fifo__wr_valid = wr_valid;
  assign wr_ready = u_fifo__wr_ready;
  assign rd_data = u_fifo__rd_data;
  assign rd_valid = u_fifo__rd_valid;
  assign u_fifo__rd_ready = rd_ready;

  sync_fifo #(.DATA_WIDTH(DATA_WIDTH), .DEPTH(DEPTH), .ADDR_WIDTH(ADDR_WIDTH)) u_fifo (
    .clk(clk),
    .rst_n(rst_n),
    .wr_valid(u_fifo__wr_valid),
    .wr_ready(u_fifo__wr_ready),
    .wr_data(u_fifo__wr_data),
    .rd_valid(u_fifo__rd_valid),
    .rd_ready(u_fifo__rd_ready),
    .rd_data(u_fifo__rd_data)
  );

endmodule

`timescale 1ns/1ps

module tb_top;
  reg clk;
  reg rst_n;
  reg wr_en;
  reg rd_en;
  reg [7:0] din;
  wire [7:0] dout;
  wire full;
  wire empty;

  top dut (
    .clk(clk),
    .rst_n(rst_n),
    .wr_en(wr_en),
    .rd_en(rd_en),
    .din(din),
    .dout(dout),
    .full(full),
    .empty(empty)
  );

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  task write_word;
    input [7:0] value;
    begin
      @(negedge clk);
      din = value;
      wr_en = 1'b1;
      @(negedge clk);
      wr_en = 1'b0;
      #1;
    end
  endtask

  task read_expect;
    input [7:0] expected;
    begin
      @(negedge clk);
      rd_en = 1'b1;
      @(negedge clk);
      rd_en = 1'b0;
      #1;
      if (dout !== expected) begin
        $display("TEST_FAIL expected dout=%0d got %0d", expected, dout);
        $finish;
      end
    end
  endtask

  initial begin
    rst_n = 1'b0;
    wr_en = 1'b0;
    rd_en = 1'b0;
    din = 8'd0;
    repeat (2) @(posedge clk);
    rst_n = 1'b1;

    write_word(8'd10);
    write_word(8'd11);
    write_word(8'd12);
    write_word(8'd13);
    if (full !== 1'b1) begin
      $display("TEST_FAIL fifo should be full after four writes");
      $finish;
    end

    write_word(8'd99);
    @(negedge clk);
    rd_en = 1'b1;
    @(negedge clk);
    rd_en = 1'b0;
    #1;
    if (dout !== 8'd10) begin
      $display("TEST_FAIL overflow guard changed stored data");
      $finish;
    end
    read_expect(8'd11);
    read_expect(8'd12);
    read_expect(8'd13);

    if (empty !== 1'b1) begin
      $display("TEST_FAIL fifo should be empty after four reads");
      $finish;
    end
    @(negedge clk);
    rd_en = 1'b1;
    @(negedge clk);
    rd_en = 1'b0;
    write_word(8'd77);
    @(negedge clk);
    rd_en = 1'b1;
    @(negedge clk);
    rd_en = 1'b0;
    #1;
    if (dout !== 8'd77) begin
      $display("TEST_FAIL underflow guard advanced read pointer");
      $finish;
    end

    write_word(8'd21);
    @(negedge clk);
    din = 8'd22;
    wr_en = 1'b1;
    rd_en = 1'b1;
    @(negedge clk);
    wr_en = 1'b0;
    rd_en = 1'b0;
    #1;
    if (dout !== 8'd21 || empty !== 1'b0 || full !== 1'b0) begin
      $display("TEST_FAIL simultaneous push-pop changed occupancy");
      $finish;
    end
    read_expect(8'd22);
    if (empty !== 1'b1) begin
      $display("TEST_FAIL simultaneous push-pop left wrong count");
      $finish;
    end

    $display("TEST_PASS");
    $finish;
  end
  initial begin
    #100000;
    $display("TEST_FAIL timeout waiting for expected input/output behavior");
    $finish;
  end

endmodule

