module fifo_core #(parameter DATA_WIDTH = 8, parameter DEPTH = 4, parameter ADDR_WIDTH = 2) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire out_valid,
    input wire out_ready,
    output wire [DATA_WIDTH-1:0] out_data
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
    localparam [ADDR_WIDTH-1:0] FIFO_ZERO_ADDR = {ADDR_WIDTH{1'b0}};
    localparam [ADDR_WIDTH-1:0] FIFO_LAST_ADDR = {ADDR_WIDTH{1'b1}};
    localparam [ADDR_WIDTH:0] FIFO_ZERO_COUNT = {(ADDR_WIDTH+1){1'b0}};
    localparam [ADDR_WIDTH:0] FIFO_ONE_COUNT = {{ADDR_WIDTH{1'b0}}, 1'b1};
    localparam [ADDR_WIDTH:0] FIFO_DEPTH_COUNT = {1'b1, {ADDR_WIDTH{1'b0}}};

    reg [DATA_WIDTH-1:0] fifo_storage [0:DEPTH-1];
    reg [DATA_WIDTH-1:0] fifo_out_data_reg;
    reg fifo_out_valid_reg;
    reg [ADDR_WIDTH-1:0] fifo_wr_ptr;
    reg [ADDR_WIDTH-1:0] fifo_rd_ptr;
    reg [ADDR_WIDTH:0] fifo_count;

    wire fifo_push;
    wire fifo_pop;
    wire [ADDR_WIDTH-1:0] fifo_wr_ptr_next;
    wire [ADDR_WIDTH-1:0] fifo_rd_ptr_next;

    reg [ADDR_WIDTH:0] fifo_count_next;
    reg [DATA_WIDTH-1:0] fifo_out_data_next;

    assign in_ready = (fifo_count != FIFO_DEPTH_COUNT);
    assign out_valid = fifo_out_valid_reg;
    assign out_data = fifo_out_data_reg;

    assign fifo_push = in_valid & in_ready;
    assign fifo_pop = fifo_out_valid_reg & out_ready;

    assign fifo_wr_ptr_next = (fifo_wr_ptr == FIFO_LAST_ADDR) ? FIFO_ZERO_ADDR : (fifo_wr_ptr + {{(ADDR_WIDTH-1){1'b0}}, 1'b1});
    assign fifo_rd_ptr_next = (fifo_rd_ptr == FIFO_LAST_ADDR) ? FIFO_ZERO_ADDR : (fifo_rd_ptr + {{(ADDR_WIDTH-1){1'b0}}, 1'b1});

    always @* begin
      fifo_count_next = fifo_count;
      case ({fifo_push, fifo_pop})
        2'b00: fifo_count_next = fifo_count;
        2'b01: fifo_count_next = fifo_count - {{ADDR_WIDTH{1'b0}}, 1'b1};
        2'b10: fifo_count_next = fifo_count + {{ADDR_WIDTH{1'b0}}, 1'b1};
        2'b11: fifo_count_next = fifo_count;
        default: fifo_count_next = fifo_count;
      endcase
    end

    always @* begin
      fifo_out_data_next = fifo_out_data_reg;
      if (fifo_count_next == FIFO_ZERO_COUNT) begin
        fifo_out_data_next = {DATA_WIDTH{1'b0}};
      end else if ((fifo_count == FIFO_ZERO_COUNT) && fifo_push) begin
        fifo_out_data_next = in_data;
      end else if (fifo_pop) begin
        if (fifo_push && (fifo_count == FIFO_ONE_COUNT)) begin
          fifo_out_data_next = in_data;
        end else begin
          fifo_out_data_next = fifo_storage[fifo_rd_ptr_next];
        end
      end
    end

    always @(posedge clk) begin
      if (!rst_n) begin
        fifo_out_data_reg <= {DATA_WIDTH{1'b0}};
        fifo_out_valid_reg <= 1'b0;
        fifo_wr_ptr <= FIFO_ZERO_ADDR;
        fifo_rd_ptr <= FIFO_ZERO_ADDR;
        fifo_count <= FIFO_ZERO_COUNT;
      end else begin
        if (fifo_push) begin
          fifo_storage[fifo_wr_ptr] <= in_data;
          fifo_wr_ptr <= fifo_wr_ptr_next;
        end

        if (fifo_pop) begin
          fifo_rd_ptr <= fifo_rd_ptr_next;
        end

        fifo_count <= fifo_count_next;
        fifo_out_valid_reg <= (fifo_count_next != FIFO_ZERO_COUNT);
        fifo_out_data_reg <= fifo_out_data_next;
      end
    end
  // SR2FPGA_BEHAVIOR_END
endmodule

module top #(parameter DATA_WIDTH = 8, parameter DEPTH = 4, parameter ADDR_WIDTH = 2) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire out_valid,
    input wire out_ready,
    output wire [DATA_WIDTH-1:0] out_data
);

  wire u_fifo__in_valid;
  wire u_fifo__in_ready;
  wire [DATA_WIDTH-1:0] u_fifo__in_data;
  wire u_fifo__out_valid;
  wire u_fifo__out_ready;
  wire [DATA_WIDTH-1:0] u_fifo__out_data;

  assign u_fifo__in_data = in_data;
  assign u_fifo__in_valid = in_valid;
  assign in_ready = u_fifo__in_ready;
  assign out_data = u_fifo__out_data;
  assign out_valid = u_fifo__out_valid;
  assign u_fifo__out_ready = out_ready;

  fifo_core #(.DATA_WIDTH(DATA_WIDTH), .DEPTH(DEPTH), .ADDR_WIDTH(ADDR_WIDTH)) u_fifo (
    .clk(clk),
    .rst_n(rst_n),
    .in_valid(u_fifo__in_valid),
    .in_ready(u_fifo__in_ready),
    .in_data(u_fifo__in_data),
    .out_valid(u_fifo__out_valid),
    .out_ready(u_fifo__out_ready),
    .out_data(u_fifo__out_data)
  );

endmodule

`timescale 1ns/1ps

module tb_top;
  reg clk;
  reg rst_n;
  reg wr_en;
  reg rd_en;
  reg [7:0] din;
  wire [7:0] dout;
  wire full;
  wire empty;

  top dut (
    .clk(clk),
    .rst_n(rst_n),
    .wr_en(wr_en),
    .rd_en(rd_en),
    .din(din),
    .dout(dout),
    .full(full),
    .empty(empty)
  );

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  task write_word;
    input [7:0] value;
    begin
      @(negedge clk);
      din = value;
      wr_en = 1'b1;
      @(negedge clk);
      wr_en = 1'b0;
      #1;
    end
  endtask

  task read_expect;
    input [7:0] expected;
    begin
      @(negedge clk);
      rd_en = 1'b1;
      @(negedge clk);
      rd_en = 1'b0;
      #1;
      if (dout !== expected) begin
        $display("TEST_FAIL expected dout=%0d got %0d", expected, dout);
        $finish;
      end
    end
  endtask

  initial begin
    rst_n = 1'b0;
    wr_en = 1'b0;
    rd_en = 1'b0;
    din = 8'd0;
    repeat (2) @(posedge clk);
    rst_n = 1'b1;

    write_word(8'd10);
    write_word(8'd11);
    write_word(8'd12);
    write_word(8'd13);
    if (full !== 1'b1) begin
      $display("TEST_FAIL fifo should be full after four writes");
      $finish;
    end

    write_word(8'd99);
    @(negedge clk);
    rd_en = 1'b1;
    @(negedge clk);
    rd_en = 1'b0;
    #1;
    if (dout !== 8'd10) begin
      $display("TEST_FAIL overflow guard changed stored data");
      $finish;
    end
    read_expect(8'd11);
    read_expect(8'd12);
    read_expect(8'd13);

    if (empty !== 1'b1) begin
      $display("TEST_FAIL fifo should be empty after four reads");
      $finish;
    end
    @(negedge clk);
    rd_en = 1'b1;
    @(negedge clk);
    rd_en = 1'b0;
    write_word(8'd77);
    @(negedge clk);
    rd_en = 1'b1;
    @(negedge clk);
    rd_en = 1'b0;
    #1;
    if (dout !== 8'd77) begin
      $display("TEST_FAIL underflow guard advanced read pointer");
      $finish;
    end

    write_word(8'd21);
    @(negedge clk);
    din = 8'd22;
    wr_en = 1'b1;
    rd_en = 1'b1;
    @(negedge clk);
    wr_en = 1'b0;
    rd_en = 1'b0;
    #1;
    if (dout !== 8'd21 || empty !== 1'b0 || full !== 1'b0) begin
      $display("TEST_FAIL simultaneous push-pop changed occupancy");
      $finish;
    end
    read_expect(8'd22);
    if (empty !== 1'b1) begin
      $display("TEST_FAIL simultaneous push-pop left wrong count");
      $finish;
    end

    $display("TEST_PASS");
    $finish;
  end
  initial begin
    #100000;
    $display("TEST_FAIL timeout waiting for expected input/output behavior");
    $finish;
  end

endmodule

