module fir_core #(parameter DATA_WIDTH = 8, parameter TAPS = 4) (
    input wire clk,
    input wire rst_n,
    input wire [7:0] data_in,
    input wire valid_in,
    output wire ready_out,
    output wire [7:0] data_out,
    output wire valid_out
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
    // Declare internal registers for delay line
    reg [DATA_WIDTH-1:0] delay_line [0:TAPS-1];
    reg [DATA_WIDTH-1:0] data_in_reg;
    reg valid_in_reg;

    // Output registers
    reg [DATA_WIDTH-1:0] data_out_reg;
    reg valid_out_reg;
    reg ready_out_reg;

    // Internal signals for computation
    reg [DATA_WIDTH*2-1:0] products [0:TAPS-1];
    reg [DATA_WIDTH*2+3:0] accumulator;

    // Coefficients array - using default 1,1,1,1 for 4-tap filter
    reg [DATA_WIDTH-1:0] coefficients [0:TAPS-1];

    // Initialize coefficients
    integer i;
    initial begin
      for (i = 0; i < TAPS; i = i + 1) begin
        coefficients[i] = 8'd1;  // Default coefficient value
      end
    end

    // Main processing logic
    always @(posedge clk) begin
      if (!rst_n) begin
        // Reset all delay elements
        integer j;
        for (j = 0; j < TAPS; j = j + 1) begin
          delay_line[j] <= {DATA_WIDTH{1'b0}};
        end
        data_out_reg <= {DATA_WIDTH{1'b0}};
        valid_out_reg <= 1'b0;
        ready_out_reg <= 1'b1;  // Ready to accept data when reset is released
        data_in_reg <= {DATA_WIDTH{1'b0}};
        valid_in_reg <= 1'b0;
      end else begin
        // Register inputs
        data_in_reg <= data_in;
        valid_in_reg <= valid_in;

        // Update delay line when valid input
        if (valid_in) begin
          // Shift delay line
          integer k;
          for (k = TAPS-1; k > 0; k = k - 1) begin
            delay_line[k] <= delay_line[k-1];
          end
          delay_line[0] <= data_in;
        end

        // Compute FIR output
        // First compute products
        integer m;
        for (m = 0; m < TAPS; m = m + 1) begin
          products[m] <= $signed(delay_line[m]) * $signed(coefficients[m]);
        end

        // Then accumulate products
        accumulator <= 0;
        integer n;
        for (n = 0; n < TAPS; n = n + 1) begin
          accumulator <= accumulator + $signed(products[n]);
        end

        // Output the accumulated result
        data_out_reg <= accumulator[DATA_WIDTH-1:0];

        // Valid output follows input with appropriate latency
        // Assuming 4 cycles for full computation (input -> delay -> multiply -> accumulate -> output)
        valid_out_reg <= valid_in_reg;  // This should reflect actual pipeline latency

        // Ready signal indicates we can accept new data
        ready_out_reg <= 1'b1;  // Always ready since we're streaming
      end
    end

    // Second stage to properly pipeline the output
    reg [DATA_WIDTH-1:0] data_out_reg2;
    reg valid_out_reg2;

    always @(posedge clk) begin
      if (!rst_n) begin
        data_out_reg2 <= {DATA_WIDTH{1'b0}};
        valid_out_reg2 <= 1'b0;
      end else begin
        data_out_reg2 <= data_out_reg;
        valid_out_reg2 <= valid_out_reg;
      end
    end

    // Third stage to match expected latency
    reg [DATA_WIDTH-1:0] data_out_reg3;
    reg valid_out_reg3;

    always @(posedge clk) begin
      if (!rst_n) begin
        data_out_reg3 <= {DATA_WIDTH{1'b0}};
        valid_out_reg3 <= 1'b0;
      end else begin
        data_out_reg3 <= data_out_reg2;
        valid_out_reg3 <= valid_out_reg2;
      end
    end

    // Final output stage
    always @(posedge clk) begin
      if (!rst_n) begin
        data_out <= {DATA_WIDTH{1'b0}};
        valid_out <= 1'b0;
      end else begin
        data_out <= data_out_reg3;
        valid_out <= valid_out_reg3;
      end
    end

    // Ready output is always high since we accept data every cycle
    assign ready_out = 1'b1;

    // Unused signal reduction to prevent warnings
    wire _unused_signals = &{1'b0, data_in_reg, valid_in_reg};
  // SR2FPGA_BEHAVIOR_END
endmodule

module top #(parameter DATA_WIDTH = 8, parameter COEFFICIENTS = [1, 1, 1, 1], parameter TAPS = 4) (
    input wire clk,
    input wire rst_n,
    input wire [7:0] data_in,
    input wire valid_in,
    output wire ready_out,
    output wire [7:0] data_out,
    output wire valid_out
);

  wire [7:0] fir_inst__data_in;
  wire fir_inst__valid_in;
  wire fir_inst__ready_out;
  wire [7:0] fir_inst__data_out;
  wire fir_inst__valid_out;

  assign fir_inst__data_in = data_in;
  assign data_out = fir_inst__data_out;

  fir_core #(.DATA_WIDTH(DATA_WIDTH), .TAPS(TAPS)) fir_inst (
    .clk(clk),
    .rst_n(rst_n),
    .data_in(fir_inst__data_in),
    .valid_in(fir_inst__valid_in),
    .ready_out(fir_inst__ready_out),
    .data_out(fir_inst__data_out),
    .valid_out(fir_inst__valid_out)
  );

endmodule

`timescale 1ns/1ps

module tb_top;
  reg clk;
  reg rst_n;
  reg sample_valid;
  wire sample_ready;
  reg signed [7:0] sample;
  wire result_valid;
  reg result_ready;
  wire signed [10:0] result;
  localparam RESULT_WIDTH = 11;
  localparam INPUT_RECORD_WIDTH = 11;
  localparam EXPECTED_RECORD_WIDTH = 12;
  localparam MAX_ORACLE_TRANSACTIONS = 4096;
  reg [INPUT_RECORD_WIDTH-1:0] oracle_inputs [0:MAX_ORACLE_TRANSACTIONS-1];
  reg [EXPECTED_RECORD_WIDTH-1:0] oracle_expected [0:MAX_ORACLE_TRANSACTIONS-1];
  reg [INPUT_RECORD_WIDTH-1:0] oracle_input_record;
  reg [EXPECTED_RECORD_WIDTH-1:0] oracle_expected_record;
  reg signed [RESULT_WIDTH-1:0] oracle_expected_result;
  reg signed [RESULT_WIDTH-1:0] oracle_held_result;
  string oracle_input_path;
  string oracle_expected_path;
  string oracle_scenario_id;
  string oracle_scenario_class;
  integer oracle_enabled;
  integer oracle_transaction_count;
  integer oracle_item_index;
  integer oracle_stall_index;
  integer oracle_stall_cycles;

  top dut (
    .clk(clk),
    .rst_n(rst_n),
    .sample_valid(sample_valid),
    .sample_ready(sample_ready),
    .sample(sample),
    .result_valid(result_valid),
    .result_ready(result_ready),
    .result(result)
  );

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  task send_and_expect;
    input signed [7:0] value;
    input signed [10:0] expected;
    begin
      @(negedge clk);
      while (sample_ready !== 1'b1) begin
        @(negedge clk);
      end
      sample = value;
      sample_valid = 1'b1;
      @(posedge clk);
      #1;
      if (result_valid !== 1'b1) begin
        $display("TEST_FAIL result_valid was not asserted");
        $finish;
      end
      if (result !== expected) begin
        $display("TEST_FAIL expected result=%0d got %0d", expected, result);
        $finish;
      end
      @(negedge clk);
      sample_valid = 1'b0;
    end
  endtask

  task oracle_reset_dut;
    begin
      @(negedge clk);
      rst_n = 1'b0;
      sample_valid = 1'b0;
      result_ready = 1'b1;
      repeat (2) @(posedge clk);
      @(negedge clk);
      rst_n = 1'b1;
    end
  endtask

  initial begin
    rst_n = 1'b0;
    sample_valid = 1'b0;
    result_ready = 1'b1;
    sample = 8'sd0;
    oracle_transaction_count = 0;
    oracle_enabled = $value$plusargs("ORACLE_INPUT=%s", oracle_input_path);
    if (oracle_enabled) begin
      if (!$value$plusargs("ORACLE_EXPECTED=%s", oracle_expected_path) ||
          !$value$plusargs("ORACLE_SCENARIO_ID=%s", oracle_scenario_id) ||
          !$value$plusargs("ORACLE_SCENARIO_CLASS=%s", oracle_scenario_class) ||
          !$value$plusargs("ORACLE_TRANSACTION_COUNT=%d", oracle_transaction_count)) begin
        $display("TEST_FAIL missing oracle plusargs");
        $finish;
      end
      if (oracle_transaction_count <= 0 || oracle_transaction_count > MAX_ORACLE_TRANSACTIONS) begin
        $display("TEST_FAIL invalid oracle transaction count");
        $finish;
      end
      $readmemh(oracle_input_path, oracle_inputs);
      $readmemh(oracle_expected_path, oracle_expected);
      repeat (2) @(posedge clk);
      rst_n = 1'b1;
      for (oracle_item_index = 0; oracle_item_index < oracle_transaction_count; oracle_item_index = oracle_item_index + 1) begin
        oracle_input_record = oracle_inputs[oracle_item_index];
        oracle_expected_record = oracle_expected[oracle_item_index];
        oracle_expected_result = oracle_expected_record[RESULT_WIDTH-1:0];
        oracle_stall_cycles = oracle_input_record[10:9];
        if (oracle_input_record[8]) begin
          oracle_reset_dut;
        end
        @(negedge clk);
        while (sample_ready !== 1'b1) begin
          @(negedge clk);
        end
        result_ready = oracle_stall_cycles == 0;
        sample = oracle_input_record[7:0];
        sample_valid = 1'b1;
        @(posedge clk);
        #1;
        if (!oracle_expected_record[RESULT_WIDTH] || result_valid !== 1'b1 || result !== oracle_expected_result) begin
          $display("SR2FPGA_MISMATCH {\"scenario_id\":\"%0s\",\"class\":\"%0s\",\"item_index\":%0d,\"expected\":\"0x%0h\",\"actual\":\"0x%0h\"}",
                   oracle_scenario_id, oracle_scenario_class, oracle_item_index, oracle_expected_result, result);
          $display("TEST_FAIL functional mismatch");
          $finish;
        end
        oracle_held_result = result;
        @(negedge clk);
        sample_valid = 1'b0;
        for (oracle_stall_index = 0; oracle_stall_index < oracle_stall_cycles; oracle_stall_index = oracle_stall_index + 1) begin
          @(posedge clk);
          #1;
          if (result_valid !== 1'b1 || result !== oracle_held_result) begin
            $display("SR2FPGA_MISMATCH {\"scenario_id\":\"%0s\",\"class\":\"%0s\",\"item_index\":%0d,\"expected\":\"0x%0h\",\"actual\":\"0x%0h\"}",
                     oracle_scenario_id, oracle_scenario_class, oracle_item_index, oracle_held_result, result);
            $display("TEST_FAIL result changed under backpressure");
            $finish;
          end
        end
        @(negedge clk);
        result_ready = 1'b1;
        @(posedge clk);
        #1;
        if (result_valid !== 1'b0) begin
          $display("TEST_FAIL result_valid did not clear");
          $finish;
        end
      end
      $display("TEST_PASS");
      $finish;
    end else begin
      repeat (2) @(posedge clk);
      rst_n = 1'b1;

      send_and_expect(8'sd5, 11'sd15);
      send_and_expect(-8'sd4, -11'sd22);
      send_and_expect(8'sd7, 11'sd34);

      @(negedge clk);
      rst_n = 1'b0;
      repeat (2) @(posedge clk);
      @(negedge clk);
      rst_n = 1'b1;
      send_and_expect(8'sd127, 11'sd381);

      @(posedge clk);
      #1;
      @(negedge clk);
      while (sample_ready !== 1'b1) begin
        @(negedge clk);
      end
      result_ready = 1'b0;
      sample = 8'sd9;
      sample_valid = 1'b1;
      @(posedge clk);
      #1;
      if (result_valid !== 1'b1 || result !== -11'sd227) begin
        $display("TEST_FAIL failed to capture result before backpressure");
        $finish;
      end
      @(negedge clk);
      sample = -8'sd11;
      repeat (2) begin
        @(posedge clk);
        #1;
        if (result_valid !== 1'b1 || result !== -11'sd227) begin
          $display("TEST_FAIL result changed under backpressure");
          $finish;
        end
      end
      @(negedge clk);
      sample_valid = 1'b0;
      result_ready = 1'b1;

      @(posedge clk);
      #1;
      if (result_valid !== 1'b0) begin
        $display("TEST_FAIL result_valid did not clear");
        $finish;
      end
      $display("TEST_PASS");
      $finish;
    end
  end
  initial begin
    #100000;
    $display("TEST_FAIL timeout waiting for expected input/output behavior");
    $finish;
  end

endmodule

