module coefficient_rom #(parameter COEFF_WIDTH = 8, parameter NUM_TAPS = 3) (
    input wire clk,
    input wire rst_n,
    output wire [COEFF_WIDTH-1:0] coeff_0,
    output wire [COEFF_WIDTH-1:0] coeff_1,
    output wire [COEFF_WIDTH-1:0] coeff_2
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
  assign coeff_0 = 8'd1;
  assign coeff_1 = 8'd2;
  assign coeff_2 = 8'd3;
  // SR2FPGA_BEHAVIOR_END
endmodule

module multiply_add_tree #(parameter DATA_WIDTH = 8, parameter COEFF_WIDTH = 8, parameter NUM_TAPS = 3, parameter OUTPUT_WIDTH = 16) (
    input wire clk,
    input wire rst_n,
    input wire [DATA_WIDTH-1:0] data_0,
    input wire [DATA_WIDTH-1:0] data_1,
    input wire [DATA_WIDTH-1:0] data_2,
    input wire [COEFF_WIDTH-1:0] coeff_0,
    input wire [COEFF_WIDTH-1:0] coeff_1,
    input wire [COEFF_WIDTH-1:0] coeff_2,
    output wire [OUTPUT_WIDTH-1:0] result
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
  wire signed [15:0] prod0 = $signed(data_0) * $signed(coeff_0);
  wire signed [15:0] prod1 = $signed(data_1) * $signed(coeff_1);
  wire signed [15:0] prod2 = $signed(data_2) * $signed(coeff_2);
  wire signed [17:0] sum = prod0 + prod1 + prod2;
  assign result = sum[OUTPUT_WIDTH-1:0];
  wire _unused_mac = |sum;
  // SR2FPGA_BEHAVIOR_END
endmodule

module pipeline_register #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire s_axis_tvalid,
    output wire s_axis_tready,
    input wire [DATA_WIDTH-1:0] s_axis_tdata,
    output wire m_axis_tvalid,
    input wire m_axis_tready,
    output wire [DATA_WIDTH-1:0] m_axis_tdata
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
  reg [DATA_WIDTH-1:0] data_reg;
  reg valid_reg;

  always @(posedge clk) begin
     if (!rst_n) begin
        valid_reg <= 1'b0;
        data_reg <= {DATA_WIDTH{1'b0}};
     end else begin
        if (s_axis_tvalid && s_axis_tready) begin
           data_reg <= s_axis_tdata;
        end
        if (s_axis_tvalid && s_axis_tready) begin
           valid_reg <= 1'b1;
        end else if (valid_reg && m_axis_tready) begin
           valid_reg <= 1'b0;
        end
     end
  end

  assign s_axis_tready = !valid_reg || m_axis_tready;
  assign m_axis_tvalid = valid_reg;
  assign m_axis_tdata = data_reg;
  // SR2FPGA_BEHAVIOR_END
endmodule

module shift_register #(parameter DATA_WIDTH = 8, parameter DEPTH = 3) (
    input wire clk,
    input wire rst_n,
    input wire shift_en,
    input wire [DATA_WIDTH-1:0] data_in,
    output wire [DATA_WIDTH-1:0] tap_0,
    output wire [DATA_WIDTH-1:0] tap_1,
    output wire [DATA_WIDTH-1:0] tap_2
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
  reg [DATA_WIDTH-1:0] tap_0_reg;
  reg [DATA_WIDTH-1:0] tap_1_reg;
  reg [DATA_WIDTH-1:0] tap_2_reg;

  assign tap_0 = tap_0_reg;
  assign tap_1 = tap_1_reg;
  assign tap_2 = tap_2_reg;

  always @(posedge clk) begin
     if (!rst_n) begin
        tap_0_reg <= {DATA_WIDTH{1'b0}};
        tap_1_reg <= {DATA_WIDTH{1'b0}};
        tap_2_reg <= {DATA_WIDTH{1'b0}};
     end else if (shift_en) begin
        tap_0_reg <= data_in;
        tap_1_reg <= tap_0_reg;
        tap_2_reg <= tap_1_reg;
     end
  end
  // SR2FPGA_BEHAVIOR_END
endmodule

module top #(parameter DATA_WIDTH = 8, parameter COEFF_WIDTH = 8, parameter NUM_TAPS = 3, parameter OUTPUT_WIDTH = 8, parameter DEPTH = 3) (
    input wire clk,
    input wire rst_n,
    input wire s_axis_tvalid,
    output wire s_axis_tready,
    input wire [DATA_WIDTH-1:0] s_axis_tdata,
    output wire m_axis_tvalid,
    input wire m_axis_tready,
    output wire [OUTPUT_WIDTH-1:0] m_axis_tdata
);

  wire u_shift__shift_en;
  wire [DATA_WIDTH-1:0] u_shift__data_in;
  wire [DATA_WIDTH-1:0] u_shift__tap_0;
  wire [DATA_WIDTH-1:0] u_shift__tap_1;
  wire [DATA_WIDTH-1:0] u_shift__tap_2;
  wire [COEFF_WIDTH-1:0] u_coeff_rom__coeff_0;
  wire [COEFF_WIDTH-1:0] u_coeff_rom__coeff_1;
  wire [COEFF_WIDTH-1:0] u_coeff_rom__coeff_2;
  wire [DATA_WIDTH-1:0] u_mac__data_0;
