module line_buffer #(parameter DATA_WIDTH = 8, parameter IMG_WIDTH = 640) (
    input wire clk,
    input wire rst_n,
    input wire advance,
    input wire [DATA_WIDTH-1:0] pixel_in,
    output wire [DATA_WIDTH-1:0] row0_pixel,
    output wire [DATA_WIDTH-1:0] row1_pixel,
    output wire [DATA_WIDTH-1:0] row2_pixel
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
    localparam integer ADDR_WIDTH = (IMG_WIDTH <= 2) ? 1 : $clog2(IMG_WIDTH);

    reg [DATA_WIDTH-1:0] lb_row0_mem [0:IMG_WIDTH-1];
    reg [DATA_WIDTH-1:0] lb_row1_mem [0:IMG_WIDTH-1];
    reg [ADDR_WIDTH-1:0] write_addr_reg;
    reg [DATA_WIDTH-1:0] row0_pixel_reg;
    reg [DATA_WIDTH-1:0] row1_pixel_reg;
    reg [DATA_WIDTH-1:0] row2_pixel_reg;

    assign row0_pixel = row0_pixel_reg;
    assign row1_pixel = row1_pixel_reg;
    assign row2_pixel = row2_pixel_reg;

    always @(posedge clk) begin
      if (!rst_n) begin
        write_addr_reg <= {ADDR_WIDTH{1'b0}};
        row0_pixel_reg <= {DATA_WIDTH{1'b0}};
        row1_pixel_reg <= {DATA_WIDTH{1'b0}};
        row2_pixel_reg <= {DATA_WIDTH{1'b0}};
      end else if (advance) begin
        row0_pixel_reg <= lb_row0_mem[write_addr_reg];
        row1_pixel_reg <= lb_row1_mem[write_addr_reg];
        row2_pixel_reg <= pixel_in;
        lb_row0_mem[write_addr_reg] <= lb_row1_mem[write_addr_reg];
        lb_row1_mem[write_addr_reg] <= pixel_in;
        if (write_addr_reg == IMG_WIDTH[ADDR_WIDTH-1:0] - {{(ADDR_WIDTH-1){1'b0}}, 1'b1}) begin
          write_addr_reg <= {ADDR_WIDTH{1'b0}};
        end else begin
          write_addr_reg <= write_addr_reg + {{(ADDR_WIDTH-1){1'b0}}, 1'b1};
        end
      end
    end
  // SR2FPGA_BEHAVIOR_END
endmodule

module sobel_core #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire advance,
    input wire window_valid,
    input wire [9*DATA_WIDTH-1:0] window_pixels,
    output wire magnitude_valid,
    output wire [DATA_WIDTH+3-1:0] magnitude
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
    localparam integer MAG_WIDTH = DATA_WIDTH + 3;
    localparam integer GRAD_WIDTH = DATA_WIDTH + 3;

    wire [DATA_WIDTH-1:0] p00 = window_pixels[(0*DATA_WIDTH) +: DATA_WIDTH];
    wire [DATA_WIDTH-1:0] p01 = window_pixels[(1*DATA_WIDTH) +: DATA_WIDTH];
    wire [DATA_WIDTH-1:0] p02 = window_pixels[(2*DATA_WIDTH) +: DATA_WIDTH];
    wire [DATA_WIDTH-1:0] p10 = window_pixels[(3*DATA_WIDTH) +: DATA_WIDTH];
    wire [DATA_WIDTH-1:0] p12 = window_pixels[(5*DATA_WIDTH) +: DATA_WIDTH];
    wire [DATA_WIDTH-1:0] p20 = window_pixels[(6*DATA_WIDTH) +: DATA_WIDTH];
    wire [DATA_WIDTH-1:0] p21 = window_pixels[(7*DATA_WIDTH) +: DATA_WIDTH];
    wire [DATA_WIDTH-1:0] p22 = window_pixels[(8*DATA_WIDTH) +: DATA_WIDTH];
    wire [DATA_WIDTH-1:0] p11_unused = window_pixels[(4*DATA_WIDTH) +: DATA_WIDTH];
    wire _unused_center_pixel = &{1'b0, p11_unused};

    wire signed [GRAD_WIDTH-1:0] p00_s = $signed({{(GRAD_WIDTH-DATA_WIDTH){1'b0}}, p00});
    wire signed [GRAD_WIDTH-1:0] p01_s = $signed({{(GRAD_WIDTH-DATA_WIDTH){1'b0}}, p01});
    wire signed [GRAD_WIDTH-1:0] p02_s = $signed({{(GRAD_WIDTH-DATA_WIDTH){1'b0}}, p02});
    wire signed [GRAD_WIDTH-1:0] p10_s = $signed({{(GRAD_WIDTH-DATA_WIDTH){1'b0}}, p10});
    wire signed [GRAD_WIDTH-1:0] p12_s = $signed({{(GRAD_WIDTH-DATA_WIDTH){1'b0}}, p12});
    wire signed [GRAD_WIDTH-1:0] p20_s = $signed({{(GRAD_WIDTH-DATA_WIDTH){1'b0}}, p20});
    wire signed [GRAD_WIDTH-1:0] p21_s = $signed({{(GRAD_WIDTH-DATA_WIDTH){1'b0}}, p21});
    wire signed [GRAD_WIDTH-1:0] p22_s = $signed({{(GRAD_WIDTH-DATA_WIDTH){1'b0}}, p22});

    wire signed [GRAD_WIDTH-1:0] gx_calc = (p02_s + (p12_s <<< 1) + p22_s) - (p00_s + (p10_s <<< 1) + p20_s);
    wire signed [GRAD_WIDTH-1:0] gy_calc = (p20_s + (p21_s <<< 1) + p22_s) - (p00_s + (p01_s <<< 1) + p02_s);
    wire [GRAD_WIDTH-1:0] gx_abs = gx_calc[GRAD_WIDTH-1] ? $unsigned(-gx_calc) : $unsigned(gx_calc);
    wire [GRAD_WIDTH-1:0] gy_abs = gy_calc[GRAD_WIDTH-1] ? $unsigned(-gy_calc) : $unsigned(gy_calc);
    wire [MAG_WIDTH:0] magnitude_sum = {1'b0, gx_abs} + {1'b0, gy_abs};

    reg magnitude_valid_reg;
    reg [MAG_WIDTH-1:0] magnitude_reg;

    assign magnitude_valid = magnitude_valid_reg;
    assign magnitude = magnitude_reg;

    always @(posedge clk) begin
      if (!rst_n) begin
        magnitude_valid_reg <= 1'b0;
        magnitude_reg <= {MAG_WIDTH{1'b0}};
      end else if (advance) begin
        magnitude_valid_reg <= window_valid;
        if (magnitude_sum[MAG_WIDTH]) begin
          magnitude_reg <= {MAG_WIDTH{1'b1}};
        end else begin
          magnitude_reg <= magnitude_sum[MAG_WIDTH-1:0];
        end
      end
    end
  // SR2FPGA_BEHAVIOR_END
endmodule

module stream_control #(parameter IMG_WIDTH = 640, parameter IMG_HEIGHT = 480) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    input wire in_ready,
    input wire in_last,
    output wire advance,
    output wire boundary,
    output wire last_aligned
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
    localparam integer X_WIDTH = (IMG_WIDTH <= 2) ? 1 : $clog2(IMG_WIDTH);
    localparam integer Y_WIDTH = (IMG_HEIGHT <= 2) ? 1 : $clog2(IMG_HEIGHT);

    reg [X_WIDTH-1:0] pix_x_count;
    reg [Y_WIDTH-1:0] pix_y_count;
    reg boundary_flag_reg;
    reg [3:0] last_pipeline_reg;
    reg [1:0] stream_fsm;

    wire accept_pixel = in_valid & in_ready;
    wire at_last_column = (pix_x_count == IMG_WIDTH[X_WIDTH-1:0] - {{(X_WIDTH-1){1'b0}}, 1'b1});
    wire at_last_row = (pix_y_count == IMG_HEIGHT[Y_WIDTH-1:0] - {{(Y_WIDTH-1){1'b0}}, 1'b1});
    wire next_boundary = (pix_x_count == {X_WIDTH{1'b0}}) ||
                         (pix_y_count == {Y_WIDTH{1'b0}}) ||
                         at_last_column || at_last_row;

    assign advance = accept_pixel;
    assign boundary = boundary_flag_reg;
    assign last_aligned = last_pipeline_reg[3];

    always @(posedge clk) begin
      if (!rst_n) begin
        pix_x_count <= {X_WIDTH{1'b0}};
        pix_y_count <= {Y_WIDTH{1'b0}};
        boundary_flag_reg <= 1'b1;
        last_pipeline_reg <= 4'b0000;
        stream_fsm <= IDLE[1:0];
      end else begin
        if (accept_pixel) begin
          boundary_flag_reg <= next_boundary;
          last_pipeline_reg <= {last_pipeline_reg[2:0], in_last};
          if (at_last_column) begin
            pix_x_count <= {X_WIDTH{1'b0}};
            if (at_last_row || in_last) begin
              pix_y_count <= {Y_WIDTH{1'b0}};
            end else begin
              pix_y_count <= pix_y_count + {{(Y_WIDTH-1){1'b0}}, 1'b1};
            end
          end else begin
            pix_x_count <= pix_x_count + {{(X_WIDTH-1){1'b0}}, 1'b1};
          end
        end else begin
          last_pipeline_reg <= {last_pipeline_reg[2:0], 1'b0};
        end

        case (stream_fsm)
          IDLE[1:0]: begin
            if (accept_pixel) begin
              stream_fsm <= in_last ? FLUSH[1:0] : ACTIVE[1:0];
            end
          end
          ACTIVE[1:0]: begin
            if (accept_pixel && in_last) begin
              stream_fsm <= FLUSH[1:0];
            end
          end
          FLUSH[1:0]: begin
            if (last_pipeline_reg[3]) begin
              stream_fsm <= IDLE[1:0];
            end
          end
          default: begin
            stream_fsm <= IDLE[1:0];
          end
        endcase
      end
    end
  // SR2FPGA_BEHAVIOR_END
  localparam IDLE = 0;
  localparam ACTIVE = 0;
  localparam FLUSH = 0;
  wire _unused_fsm_states = &{1'b0, (IDLE == IDLE), (ACTIVE == ACTIVE), (FLUSH == FLUSH)};
endmodule

module threshold_core #(parameter DATA_WIDTH = 8, parameter EDGE_HIGH_VALUE = 255, parameter EDGE_LOW_VALUE = 0) (
    input wire clk,
    input wire rst_n,
    input wire advance,
    input wire magnitude_valid,
    input wire [DATA_WIDTH+3-1:0] magnitude,
    input wire [DATA_WIDTH-1:0] threshold,
    input wire boundary,
    output wire edge_valid,
    output wire [DATA_WIDTH-1:0] edge_pixel,
    output wire edge_flag
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
    localparam integer MAG_WIDTH = DATA_WIDTH + 3;

    reg edge_valid_reg;
    reg [DATA_WIDTH-1:0] edge_pixel_reg;
    reg edge_flag_reg;

    wire [MAG_WIDTH-1:0] threshold_ext = {{(MAG_WIDTH-DATA_WIDTH){1'b0}}, threshold};
    wire edge_compare = magnitude >= threshold_ext;
    wire [DATA_WIDTH-1:0] edge_high_sized = EDGE_HIGH_VALUE[DATA_WIDTH-1:0];
    wire [DATA_WIDTH-1:0] edge_low_sized = EDGE_LOW_VALUE[DATA_WIDTH-1:0];

    assign edge_valid = edge_valid_reg;
    assign edge_pixel = edge_pixel_reg;
    assign edge_flag = edge_flag_reg;

    always @(posedge clk) begin
      if (!rst_n) begin
        edge_valid_reg <= 1'b0;
        edge_pixel_reg <= edge_low_sized;
        edge_flag_reg <= 1'b0;
      end else if (advance) begin
        edge_valid_reg <= magnitude_valid;
        if (boundary || !magnitude_valid) begin
          edge_pixel_reg <= edge_low_sized;
          edge_flag_reg <= 1'b0;
        end else if (edge_compare) begin
          edge_pixel_reg <= edge_high_sized;
          edge_flag_reg <= 1'b1;
        end else begin
          edge_pixel_reg <= edge_low_sized;
          edge_flag_reg <= 1'b0;
        end
      end
    end
  // SR2FPGA_BEHAVIOR_END
endmodule

