  // SR2FPGA_BEHAVIOR_BEGIN
    reg [DATA_WIDTH-1:0] win_pixel_00;
    reg [DATA_WIDTH-1:0] win_pixel_01;
    reg [DATA_WIDTH-1:0] win_pixel_02;
