module accumulator_core #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire sample_valid,
    input wire [DATA_WIDTH-1:0] sample,
    input wire sample_ready,
    output wire [DATA_WIDTH-1:0] sum
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
    reg [DATA_WIDTH-1:0] accumulator_sum_reg;
    reg [31:0] accepted_sample_count;
    wire [DATA_WIDTH:0] accumulator_sum_ext;

    assign accumulator_sum_ext = {1'b0, accumulator_sum_reg} + {1'b0, sample};
    assign sum = accumulator_sum_reg;

    always @(posedge clk) begin
      if (!rst_n) begin
        accumulator_sum_reg <= {DATA_WIDTH{1'b0}};
        accepted_sample_count <= 32'd0;
      end else if (sample_valid && sample_ready) begin
        accumulator_sum_reg <= accumulator_sum_ext[DATA_WIDTH-1:0];
        accepted_sample_count <= accepted_sample_count + 32'd1;
      end
    end

    wire _unused_accumulator_sum_carry = accumulator_sum_ext[DATA_WIDTH];
    wire _unused_accepted_sample_count = ^accepted_sample_count;
  // SR2FPGA_BEHAVIOR_END
endmodule

module skid_buffer #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire in_ready,
    output wire out_valid,
    output wire [DATA_WIDTH-1:0] out_data,
    input wire out_ready
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
    reg [DATA_WIDTH-1:0] input_buffer_data_reg;
    reg input_buffer_occupancy_fsm;

    wire input_buffer_empty;
    wire input_buffer_full;
    wire input_accept;
    wire output_accept;

    assign input_buffer_empty = (input_buffer_occupancy_fsm == 1'b0);
    assign input_buffer_full = (input_buffer_occupancy_fsm == 1'b1);
    assign in_ready = input_buffer_empty || out_ready;
    assign out_valid = input_buffer_full || in_valid;
    assign out_data = input_buffer_full ? input_buffer_data_reg : in_data;
    assign input_accept = in_valid && in_ready;
    assign output_accept = out_valid && out_ready;

    always @(posedge clk) begin
      if (!rst_n) begin
        input_buffer_occupancy_fsm <= 1'b0;
        input_buffer_data_reg <= {DATA_WIDTH{1'b0}};
      end else begin
        case ({input_accept, output_accept})
          2'b00: begin
            input_buffer_occupancy_fsm <= input_buffer_occupancy_fsm;
            input_buffer_data_reg <= input_buffer_data_reg;
          end
          2'b01: begin
            input_buffer_occupancy_fsm <= 1'b0;
            input_buffer_data_reg <= input_buffer_data_reg;
          end
          2'b10: begin
            input_buffer_occupancy_fsm <= 1'b1;
            input_buffer_data_reg <= in_data;
          end
          2'b11: begin
            input_buffer_occupancy_fsm <= 1'b0;
            input_buffer_data_reg <= input_buffer_data_reg;
          end
          default: begin
            input_buffer_occupancy_fsm <= 1'b0;
            input_buffer_data_reg <= {DATA_WIDTH{1'b0}};
          end
        endcase
      end
    end

    wire _unused_input_buffer_state_flags = &{1'b0, input_buffer_empty, input_buffer_full};
  // SR2FPGA_BEHAVIOR_END
  localparam empty = 0;
  localparam full = 0;
  wire _unused_fsm_states = &{1'b0, (empty == empty), (full == full)};
endmodule

module top #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire in_ready,
    output wire sample_valid,
    output wire [DATA_WIDTH-1:0] sum
);

  wire input_buffer__in_valid;
  wire [DATA_WIDTH-1:0] input_buffer__in_data;
  wire input_buffer__in_ready;
  wire input_buffer__out_valid;
  wire [DATA_WIDTH-1:0] input_buffer__out_data;
  wire input_buffer__out_ready;
  wire accumulator__sample_valid;
  wire [DATA_WIDTH-1:0] accumulator__sample;
  wire accumulator__sample_ready;
  wire [DATA_WIDTH-1:0] accumulator__sum;

  assign input_buffer__in_valid = in_valid;
  assign in_ready = input_buffer__in_ready;
  assign input_buffer__in_data = in_data;
  assign accumulator__sample = input_buffer__out_data;
  assign accumulator__sample_valid = input_buffer__out_valid;
  assign input_buffer__out_ready = accumulator__sample_ready;
  assign sample_valid = accumulator__sample_valid;
  assign accumulator__sample_ready = input_buffer__out_ready;
  assign sum = accumulator__sum;

  skid_buffer #(.DATA_WIDTH(DATA_WIDTH)) input_buffer (
    .clk(clk),
    .rst_n(rst_n),
    .in_valid(input_buffer__in_valid),
    .in_data(input_buffer__in_data),
    .in_ready(input_buffer__in_ready),
    .out_valid(input_buffer__out_valid),
    .out_data(input_buffer__out_data),
    .out_ready(input_buffer__out_ready)
  );

  accumulator_core #(.DATA_WIDTH(DATA_WIDTH)) accumulator (
    .clk(clk),
    .rst_n(rst_n),
    .sample_valid(accumulator__sample_valid),
    .sample(accumulator__sample),
    .sample_ready(accumulator__sample_ready),
    .sum(accumulator__sum)
  );

endmodule

`timescale 1ns/1ps

module tb_top;
  reg clk;
  reg rst_n;
  reg in_valid;
  wire in_ready;
  reg [7:0] in_data;
  reg accum_ready;
  wire sample_valid;
  wire [11:0] sum;

  top dut (
    .clk(clk),
    .rst_n(rst_n),
    .in_valid(in_valid),
    .in_ready(in_ready),
    .in_data(in_data),
    .accum_ready(accum_ready),
    .sample_valid(sample_valid),
    .sum(sum)
  );

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  task send_sample;
    input [7:0] value;
    begin
      @(negedge clk);
      while (!in_ready) @(negedge clk);
      in_valid = 1'b1;
      in_data = value;
      @(negedge clk);
      in_valid = 1'b0;
      in_data = 8'd0;
    end
  endtask

  initial begin
    rst_n = 1'b0;
    in_valid = 1'b0;
    in_data = 8'd0;
    accum_ready = 1'b1;
    repeat (2) @(posedge clk);
    rst_n = 1'b1;

    send_sample(8'd3);
    wait (sum == 12'd3);

    @(negedge clk);
    accum_ready = 1'b0;
    send_sample(8'd4);
    repeat (3) begin
      @(posedge clk);
      #1;
      if (sample_valid !== 1'b1) begin
        $display("TEST_FAIL stalled sample_valid dropped");
        $finish;
      end
      if (sum !== 12'd3) begin
        $display("TEST_FAIL accumulator advanced while stalled sum=%0d", sum);
        $finish;
      end
    end

    @(negedge clk);
    accum_ready = 1'b1;
    @(posedge clk);
    #1;
    #1;

    if (sum !== 12'd7) begin
      $display("TEST_FAIL expected sum=7 got %0d", sum);
      $finish;
    end
    if (in_ready !== 1'b1) begin
      $display("TEST_FAIL in_ready not asserted");
      $finish;
    end
    $display("TEST_PASS");
    $finish;
  end
  initial begin
    #100000;
    $display("TEST_FAIL timeout waiting for expected input/output behavior");
    $finish;
  end

endmodule

