module accumulator_core #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire sample_valid,
    input wire sample_ready,
    input wire [DATA_WIDTH-1:0] sample_data,
    output wire accum_valid,
    input wire accum_ready,
    output wire [DATA_WIDTH-1:0] accum_data
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
    reg [DATA_WIDTH-1:0] accumulator_sum_reg;
    wire [DATA_WIDTH:0] accumulator_sum_ext;
    wire transfer_en;

    assign transfer_en = sample_valid & sample_ready;
    assign accumulator_sum_ext = {1'b0, accumulator_sum_reg} + {1'b0, sample_data};
    wire _unused_accumulator_carry = accumulator_sum_ext[DATA_WIDTH];

    assign accum_valid = sample_valid & sample_ready;
    assign accum_data = accumulator_sum_ext[DATA_WIDTH-1:0];
    assign sample_ready = accum_ready;

    always @(posedge clk) begin
      if (!rst_n) begin
        accumulator_sum_reg <= {DATA_WIDTH{1'b0}};
      end else if (transfer_en) begin
        accumulator_sum_reg <= accumulator_sum_ext[DATA_WIDTH-1:0];
      end
    end
  // SR2FPGA_BEHAVIOR_END
endmodule

module skid_buffer #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire out_valid,
    input wire out_ready,
    output wire [DATA_WIDTH-1:0] out_data
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
    reg [DATA_WIDTH-1:0] in0_skid_storage;
    reg storage_valid_reg;

    wire input_accept;
    wire output_accept;
    wire bypass_path;

    assign in_ready = (~storage_valid_reg) | out_ready;
    assign out_valid = storage_valid_reg | in_valid;
    assign bypass_path = ~storage_valid_reg;
    assign out_data = storage_valid_reg ? in0_skid_storage : in_data;

    assign input_accept = in_valid & in_ready;
    assign output_accept = out_valid & out_ready;

    always @(posedge clk) begin
      if (!rst_n) begin
        storage_valid_reg <= 1'b0;
        in0_skid_storage <= {DATA_WIDTH{1'b0}};
      end else begin
        if (output_accept) begin
          storage_valid_reg <= 1'b0;
        end

        if (input_accept & ~output_accept) begin
          storage_valid_reg <= 1'b1;
          in0_skid_storage <= in_data;
        end else if (input_accept & output_accept & ~bypass_path) begin
          storage_valid_reg <= 1'b1;
          in0_skid_storage <= in_data;
        end
      end
    end
  // SR2FPGA_BEHAVIOR_END
endmodule

module stream_join #(parameter DATA_WIDTH = 8) (
    input wire in0_valid,
    output wire in0_ready,
    input wire [DATA_WIDTH-1:0] in0_data,
    input wire in1_valid,
    output wire in1_ready,
    input wire [DATA_WIDTH-1:0] in1_data,
    output wire out_valid,
    input wire out_ready,
    output wire [DATA_WIDTH-1:0] out_data
);
  // SR2FPGA_BEHAVIOR_BEGIN
    wire paired_valid;
    wire paired_accept;
    wire [DATA_WIDTH:0] joined_sum_ext;

    assign paired_valid = in0_valid & in1_valid;
    assign paired_accept = paired_valid & out_ready;
    assign joined_sum_ext = {1'b0, in0_data} + {1'b0, in1_data};
    wire _unused_joined_carry = joined_sum_ext[DATA_WIDTH];

    assign out_valid = paired_valid;
    assign out_data = joined_sum_ext[DATA_WIDTH-1:0];
    assign in0_ready = in1_valid & out_ready;
    assign in1_ready = in0_valid & out_ready;
    wire _unused_paired_accept = paired_accept;
  // SR2FPGA_BEHAVIOR_END
endmodule

module stream_stage #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
