module accumulator_core #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire sample_valid,
    input wire [DATA_WIDTH-1:0] sample_data,
    output wire sample_ready,
    output wire out_valid,
    output wire [DATA_WIDTH-1:0] out_data,
    input wire out_ready
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
    reg [DATA_WIDTH-1:0] accumulator_value_reg;
    reg [DATA_WIDTH-1:0] next_accumulator_value;
    reg out_valid_reg;
    reg [DATA_WIDTH-1:0] out_data_reg;

    always @(*) begin
      next_accumulator_value = accumulator_value_reg + sample_data;
    end

    always @(posedge clk) begin
      if (!rst_n) begin
        accumulator_value_reg <= {DATA_WIDTH{1'b0}};
        out_valid_reg <= 1'b0;
        out_data_reg <= {DATA_WIDTH{1'b0}};
      end else begin
        if (sample_valid && sample_ready) begin
          accumulator_value_reg <= next_accumulator_value;
        end
        if (sample_valid && sample_ready) begin
          out_valid_reg <= 1'b1;
          out_data_reg <= next_accumulator_value;
        end else if (out_ready) begin
          out_valid_reg <= 1'b0;
        end
      end
    end

    assign sample_ready = 1'b1;
    assign out_valid = out_valid_reg;
    assign out_data = out_data_reg;
  // SR2FPGA_BEHAVIOR_END
endmodule

module skid_buffer #(parameter DATA_WIDTH = 32) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire in_ready,
    output wire out_valid,
    output wire [DATA_WIDTH-1:0] out_data,
    input wire out_ready
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
    reg buffer_valid;
    reg [DATA_WIDTH-1:0] buffer_data;

    always @(posedge clk) begin
      if (!rst_n) begin
        buffer_valid <= 1'b0;
        buffer_data <= {DATA_WIDTH{1'b0}};
      end else begin
        if (out_ready && buffer_valid) begin
          buffer_valid <= 1'b0;
        end
        if (in_valid && !buffer_valid && in_ready) begin
          buffer_valid <= 1'b1;
          buffer_data <= in_data;
        end
      end
    end

    assign in_ready = !buffer_valid || out_ready;
    assign out_valid = in_valid || buffer_valid;
    assign out_data = buffer_valid ? buffer_data : in_data;
  // SR2FPGA_BEHAVIOR_END
endmodule

module stream_join #(parameter WIDTH_A = 8, parameter WIDTH_B = 8, parameter OUTPUT_WIDTH = 16) (
    input wire clk,
    input wire rst_n,
    input wire a_valid,
    input wire [WIDTH_A-1:0] a_data,
    output wire a_ready,
    input wire b_valid,
    input wire [WIDTH_B-1:0] b_data,
    output wire b_ready,
    output wire out_valid,
    output wire [OUTPUT_WIDTH-1:0] out_data,
    input wire out_ready
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
    wire both_valid = a_valid && b_valid;
    wire [WIDTH_A-1:0] extended_a = a_data;
    wire [WIDTH_B-1:0] extended_b = b_data;
    wire [OUTPUT_WIDTH-1:0] joined_result = extended_a + extended_b;

    assign a_ready = out_ready && b_valid;
    assign b_ready = out_ready && a_valid;
    assign out_valid = both_valid;
    assign out_data = joined_result;
  // SR2FPGA_BEHAVIOR_END
endmodule

module stream_stage #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    input wire [DATA_WIDTH-1:0] in_data,
    output wire in_ready,
    output wire out_valid,
    output wire [DATA_WIDTH-1:0] out_data,
    input wire out_ready
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
    reg stage_valid;
    reg [DATA_WIDTH-1:0] stage_data;

    always @(posedge clk) begin
      if (!rst_n) begin
        stage_valid <= 1'b0;
        stage_data <= {DATA_WIDTH{1'b0}};
      end else begin
        if (out_ready) begin
          stage_valid <= 1'b0;
        end
        if (in_valid && in_ready) begin
          stage_valid <= 1'b1;
          stage_data <= in_data;
        end
      end
    end

    assign in_ready = !stage_valid || out_ready;
    assign out_valid = stage_valid;
    assign out_data = stage_data;
  // SR2FPGA_BEHAVIOR_END
endmodule

