module discount_core #(parameter DATA_WIDTH = 8) (
    input wire [DATA_WIDTH-1:0] next_value_i,
    input wire [DATA_WIDTH-1:0] gamma_i,
    output wire [DATA_WIDTH-1:0] discounted_next_value_o
);
  // SR2FPGA_BEHAVIOR_BEGIN
    localparam PRODUCT_WIDTH = DATA_WIDTH * 2;

    wire signed [DATA_WIDTH-1:0] next_value_signed;
    wire [DATA_WIDTH-1:0] gamma_unsigned;
    wire signed [PRODUCT_WIDTH:0] product_ext;
    wire signed [DATA_WIDTH:0] scaled_ext;
    wire [DATA_WIDTH-1:0] discounted_next_value_slice;
    wire _unused_discount_product_bits;

    assign next_value_signed = next_value_i;
    assign gamma_unsigned = gamma_i;
    assign product_ext = $signed(next_value_signed) * $signed({1'b0, gamma_unsigned});
    assign scaled_ext = product_ext[PRODUCT_WIDTH:DATA_WIDTH];
    assign discounted_next_value_slice = scaled_ext[DATA_WIDTH-1:0];
    assign _unused_discount_product_bits = ^product_ext[DATA_WIDTH-1:0];
    assign discounted_next_value_o = discounted_next_value_slice;
  // SR2FPGA_BEHAVIOR_END
endmodule

module stream_stage #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire result_valid_i,
    output wire result_ready_o,
    input wire [DATA_WIDTH-1:0] td_error_i,
    input wire [DATA_WIDTH-1:0] updated_value_i,
    output wire out_valid,
    input wire out_ready,
    output wire [DATA_WIDTH-1:0] td_error_o,
    output wire [DATA_WIDTH-1:0] updated_value_o
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
    reg [DATA_WIDTH-1:0] output_td_error_reg;
    reg [DATA_WIDTH-1:0] output_updated_value_reg;
    reg output_valid_reg;
    reg output_stage_state_reg;

    wire output_can_load;

    assign output_can_load = (!output_valid_reg) || out_ready;
    assign result_ready_o = output_can_load;
    assign out_valid = output_valid_reg;
    assign td_error_o = output_td_error_reg;
    assign updated_value_o = output_updated_value_reg;

    always @(posedge clk) begin
      if (!rst_n) begin
        output_td_error_reg <= {DATA_WIDTH{1'b0}};
        output_updated_value_reg <= {DATA_WIDTH{1'b0}};
        output_valid_reg <= 1'b0;
        output_stage_state_reg <= IDLE;
      end else begin
        if (output_can_load) begin
          output_valid_reg <= result_valid_i;
          if (result_valid_i) begin
            output_td_error_reg <= td_error_i;
            output_updated_value_reg <= updated_value_i;
            output_stage_state_reg <= VALID;
          end else begin
            output_stage_state_reg <= IDLE;
          end
        end else begin
          output_valid_reg <= output_valid_reg;
          output_td_error_reg <= output_td_error_reg;
          output_updated_value_reg <= output_updated_value_reg;
          output_stage_state_reg <= VALID;
        end
      end
    end

    wire _unused_output_stage_state = output_stage_state_reg;
  // SR2FPGA_BEHAVIOR_END
  localparam IDLE = 0;
  localparam VALID = 0;
  wire _unused_fsm_states = &{1'b0, (IDLE == IDLE), (VALID == VALID)};
endmodule

module td_input_stage #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire [DATA_WIDTH-1:0] reward_i,
    input wire [DATA_WIDTH-1:0] value_i,
    input wire [DATA_WIDTH-1:0] next_value_i,
    input wire [DATA_WIDTH-1:0] gamma_i,
    input wire [DATA_WIDTH-1:0] alpha_i,
    output wire tuple_valid_o,
    input wire tuple_ready_i,
    output wire [DATA_WIDTH-1:0] reward_o,
    output wire [DATA_WIDTH-1:0] value_o,
    output wire [DATA_WIDTH-1:0] next_value_o,
    output wire [DATA_WIDTH-1:0] gamma_o,
    output wire [DATA_WIDTH-1:0] alpha_o
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
    reg [DATA_WIDTH-1:0] input_reward_reg;
    reg [DATA_WIDTH-1:0] input_value_reg;
    reg [DATA_WIDTH-1:0] input_next_value_reg;
    reg [DATA_WIDTH-1:0] input_gamma_reg;
    reg [DATA_WIDTH-1:0] input_alpha_reg;
    reg input_tuple_valid_reg;

    wire input_can_accept;

    assign input_can_accept = (!input_tuple_valid_reg) || tuple_ready_i;
    assign in_ready = input_can_accept;
    assign tuple_valid_o = input_tuple_valid_reg;
    assign reward_o = input_reward_reg;
    assign value_o = input_value_reg;
    assign next_value_o = input_next_value_reg;
    assign gamma_o = input_gamma_reg;
    assign alpha_o = input_alpha_reg;

    always @(posedge clk) begin
      if (!rst_n) begin
        input_reward_reg <= {DATA_WIDTH{1'b0}};
        input_value_reg <= {DATA_WIDTH{1'b0}};
        input_next_value_reg <= {DATA_WIDTH{1'b0}};
        input_gamma_reg <= {DATA_WIDTH{1'b0}};
        input_alpha_reg <= {DATA_WIDTH{1'b0}};
        input_tuple_valid_reg <= 1'b0;
      end else begin
        if (input_can_accept) begin
          input_tuple_valid_reg <= in_valid;
          if (in_valid) begin
            input_reward_reg <= reward_i;
            input_value_reg <= value_i;
            input_next_value_reg <= next_value_i;
            input_gamma_reg <= gamma_i;
            input_alpha_reg <= alpha_i;
          end
        end
      end
    end
  // SR2FPGA_BEHAVIOR_END
endmodule

module td_update_core #(parameter DATA_WIDTH = 8) (
    input wire [DATA_WIDTH-1:0] reward_i,
    input wire [DATA_WIDTH-1:0] value_i,
    input wire [DATA_WIDTH-1:0] alpha_i,
    input wire [DATA_WIDTH-1:0] discounted_next_value_i,
    output wire [DATA_WIDTH-1:0] td_error_o,
    output wire [DATA_WIDTH-1:0] updated_value_o
);
  // SR2FPGA_BEHAVIOR_BEGIN
    localparam TD_EXT_WIDTH = DATA_WIDTH + 2;
    localparam UPDATE_PRODUCT_WIDTH = DATA_WIDTH * 2;

    wire signed [DATA_WIDTH-1:0] reward_signed;
    wire signed [DATA_WIDTH-1:0] value_signed;
    wire signed [DATA_WIDTH-1:0] discounted_signed;
    wire [DATA_WIDTH-1:0] alpha_unsigned;
    wire signed [TD_EXT_WIDTH-1:0] reward_ext;
    wire signed [TD_EXT_WIDTH-1:0] value_ext;
    wire signed [TD_EXT_WIDTH-1:0] discounted_ext;
    wire signed [TD_EXT_WIDTH-1:0] td_error_ext;
    wire signed [DATA_WIDTH-1:0] td_error_sliced;
    wire signed [UPDATE_PRODUCT_WIDTH:0] alpha_product_ext;
    wire signed [DATA_WIDTH:0] alpha_scaled_ext;
    wire signed [DATA_WIDTH:0] value_update_ext;
    wire [DATA_WIDTH-1:0] updated_value_slice;
    wire _unused_td_error_high_bits;
    wire _unused_alpha_product_low_bits;

    assign reward_signed = reward_i;
    assign value_signed = value_i;
    assign discounted_signed = discounted_next_value_i;
    assign alpha_unsigned = alpha_i;
    assign reward_ext = {{(TD_EXT_WIDTH-DATA_WIDTH){reward_signed[DATA_WIDTH-1]}}, reward_signed};
    assign value_ext = {{(TD_EXT_WIDTH-DATA_WIDTH){value_signed[DATA_WIDTH-1]}}, value_signed};
    assign discounted_ext = {{(TD_EXT_WIDTH-DATA_WIDTH){discounted_signed[DATA_WIDTH-1]}}, discounted_signed};
    assign td_error_ext = reward_ext + discounted_ext - value_ext;
    assign td_error_sliced = td_error_ext[DATA_WIDTH-1:0];
    assign alpha_product_ext = $signed(td_error_sliced) * $signed({1'b0, alpha_unsigned});
    assign alpha_scaled_ext = alpha_product_ext[UPDATE_PRODUCT_WIDTH:DATA_WIDTH];
    assign value_update_ext = {value_signed[DATA_WIDTH-1], value_signed} + alpha_scaled_ext;
    assign updated_value_slice = value_update_ext[DATA_WIDTH-1:0];
    assign _unused_td_error_high_bits = ^td_error_ext[TD_EXT_WIDTH-1:DATA_WIDTH];
    assign _unused_alpha_product_low_bits = ^alpha_product_ext[DATA_WIDTH-1:0];
    assign td_error_o = td_error_sliced;
    assign updated_value_o = updated_value_slice;
  // SR2FPGA_BEHAVIOR_END
endmodule

