module discount_core #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire [DATA_WIDTH-1:0] gamma,
    input wire [DATA_WIDTH-1:0] next_value,
    output wire [DATA_WIDTH-1:0] discounted_value
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
  wire  [2*DATA_WIDTH-1:0] mult_result;
  wire  [DATA_WIDTH-1:0]   result;
  assign mult_result = gamma * next_value;
  assign result      = mult_result[DATA_WIDTH-1:0];
  assign discounted_value = result;

  always @* begin
    if (mult_result[2*DATA_WIDTH-1:DATA_WIDTH] != 0) begin
    end
  end
  // SR2FPGA_BEHAVIOR_END
endmodule

module stream_stage #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire [DATA_WIDTH-1:0] td_error_in,
    input wire [DATA_WIDTH-1:0] updated_value_in,
    output wire out_valid,
    input wire out_ready,
    output wire [DATA_WIDTH-1:0] td_error_out,
    output wire [DATA_WIDTH-1:0] updated_value_out
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
  reg  state;
  reg  [DATA_WIDTH-1:0] td_out, val_out;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state  <= 1'b0;
      td_out <= {DATA_WIDTH{1'b0}};
      val_out <= {DATA_WIDTH{1'b0}};
    end else begin
      case (state)
        1'b0: begin
          if (in_valid) begin
            td_out  <= td_error_in;
            val_out <= updated_value_in;
            state   <= 1'b1;
          end
        end
        1'b1: begin
          if (out_ready) begin
            state <= 1'b0;
          end
        end
        default: state <= 1'b0;
      endcase
    end
  end

  assign in_ready        = (state == 1'b0);
  assign out_valid       = (state == 1'b1);
  assign td_error_out    = td_out;
  assign updated_value_out = val_out;
  // SR2FPGA_BEHAVIOR_END
  localparam IDLE = 0;
  localparam VALID = 0;
  wire _unused_fsm_states = &{1'b0, (IDLE == IDLE), (VALID == VALID)};
endmodule

module td_input_stage #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire [DATA_WIDTH-1:0] reward,
    input wire [DATA_WIDTH-1:0] value,
    input wire [DATA_WIDTH-1:0] next_value,
    output wire tuple_valid,
    output wire [DATA_WIDTH-1:0] tuple_reward,
    output wire [DATA_WIDTH-1:0] tuple_value,
    output wire [DATA_WIDTH-1:0] tuple_next_value
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
  reg  tuple_valid_reg;
  reg  [DATA_WIDTH-1:0] reward_reg, value_reg, next_value_reg;
  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      tuple_valid_reg <= 1'b0;
      reward_reg      <= {DATA_WIDTH{1'b0}};
      value_reg       <= {DATA_WIDTH{1'b0}};
      next_value_reg  <= {DATA_WIDTH{1'b0}};
    end else begin
      if (in_valid && in_ready) begin
        reward_reg     <= reward;
        value_reg      <= value;
        next_value_reg <= next_value;
        tuple_valid_reg <= 1'b1;
      end else begin
        tuple_valid_reg <= 1'b0;
      end
    end
  end
  assign in_ready            = !tuple_valid_reg;
  assign tuple_valid         = tuple_valid_reg;
  assign tuple_reward        = reward_reg;
  assign tuple_value         = value_reg;
  assign tuple_next_value    = next_value_reg;
  // SR2FPGA_BEHAVIOR_END
endmodule

module td_update_core #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire [DATA_WIDTH-1:0] reward,
    input wire [DATA_WIDTH-1:0] value,
    input wire [DATA_WIDTH-1:0] discounted_value,
    input wire [DATA_WIDTH-1:0] alpha,
    output wire [DATA_WIDTH-1:0] td_error,
    output wire [DATA_WIDTH-1:0] updated_value
);
  wire _unused_clock_reset = &{1'b0, clk, rst_n};
  // SR2FPGA_BEHAVIOR_BEGIN
  wire signed [DATA_WIDTH-1:0] s_reward          = reward;
  wire signed [DATA_WIDTH-1:0] s_discounted_value = discounted_value;
  wire signed [DATA_WIDTH-1:0] s_value           = value;
  wire signed [DATA_WIDTH-1:0] s_alpha           = alpha;

  wire signed [DATA_WIDTH:0] td_error_ext = {s_reward[DATA_WIDTH-1], s_reward} + 
                                             {s_discounted_value[DATA_WIDTH-1], s_discounted_value} - 
                                             {s_value[DATA_WIDTH-1], s_value};
  assign td_error = td_error_ext[DATA_WIDTH-1:0];

  wire signed [2*DATA_WIDTH-1:0] alpha_td_product = s_alpha * $signed(td_error);
  wire signed [DATA_WIDTH:0]     updated_ext = {s_value[DATA_WIDTH-1], s_value} + 
                                               $signed({alpha_td_product[DATA_WIDTH-1], alpha_td_product[DATA_WIDTH-1:0]});
  assign updated_value = updated_ext[DATA_WIDTH-1:0];

  always @* begin
    if (alpha_td_product[2*DATA_WIDTH-1:DATA_WIDTH] != 0) begin
    end
  end
  // SR2FPGA_BEHAVIOR_END
endmodule

module top #(parameter DATA_WIDTH = 8) (
    input wire clk,
    input wire rst_n,
    input wire in_valid,
    output wire in_ready,
    input wire [DATA_WIDTH-1:0] reward,
    input wire [DATA_WIDTH-1:0] value,
    input wire [DATA_WIDTH-1:0] next_value,
    input wire [DATA_WIDTH-1:0] gamma,
    input wire [DATA_WIDTH-1:0] alpha,
    output wire out_valid,
    input wire out_ready,
    output wire [DATA_WIDTH-1:0] td_error,
    output wire [DATA_WIDTH-1:0] updated_value
);

  wire input_stage__in_valid;
  wire input_stage__in_ready;
  wire [DATA_WIDTH-1:0] input_stage__reward;
  wire [DATA_WIDTH-1:0] input_stage__value;
  wire [DATA_WIDTH-1:0] input_stage__next_value;
  wire input_stage__tuple_valid;
  wire [DATA_WIDTH-1:0] input_stage__tuple_reward;
  wire [DATA_WIDTH-1:0] input_stage__tuple_value;
  wire [DATA_WIDTH-1:0] input_stage__tuple_next_value;
  wire [DATA_WIDTH-1:0] discount__gamma;
  wire [DATA_WIDTH-1:0] discount__next_value;
  wire [DATA_WIDTH-1:0] discount__discounted_value;
  wire [DATA_WIDTH-1:0] update__reward;
  wire [DATA_WIDTH-1:0] update__value;
  wire [DATA_WIDTH-1:0] update__discounted_value;
  wire [DATA_WIDTH-1:0] update__alpha;
  wire [DATA_WIDTH-1:0] update__td_error;
  wire [DATA_WIDTH-1:0] update__updated_value;
  wire output_stage__in_valid;
  wire output_stage__in_ready;
  wire [DATA_WIDTH-1:0] output_stage__td_error_in;
  wire [DATA_WIDTH-1:0] output_stage__updated_value_in;
  wire output_stage__out_valid;
  wire output_stage__out_ready;
  wire [DATA_WIDTH-1:0] output_stage__td_error_out;
  wire [DATA_WIDTH-1:0] output_stage__updated_value_out;

  assign input_stage__in_valid = next_value;
  assign input_stage__tuple_next_value = gamma;
  assign discount__gamma = input_stage__tuple_next_value;
  assign discount__discounted_value = input_stage__tuple_value;
  assign alpha = discount__discounted_value;
  assign update__reward = alpha;
  assign output_stage__td_error_in = update__updated_value;
  assign out_valid = output_stage__updated_value_out;
  wire _unused_data_flow_signals = &{1'b0, input_stage__in_ready, out_ready};

  td_input_stage #(.DATA_WIDTH(DATA_WIDTH)) input_stage (
    .clk(clk),
    .rst_n(rst_n),
    .in_valid(input_stage__in_valid),
    .in_ready(input_stage__in_ready),
    .reward(input_stage__reward),
    .value(input_stage__value),
    .next_value(input_stage__next_value),
    .tuple_valid(input_stage__tuple_valid),
    .tuple_reward(input_stage__tuple_reward),
    .tuple_value(input_stage__tuple_value),
    .tuple_next_value(input_stage__tuple_next_value)
  );

  discount_core #(.DATA_WIDTH(DATA_WIDTH)) discount (
    .clk(clk),
    .rst_n(rst_n),
    .gamma(discount__gamma),
    .next_value(discount__next_value),
    .discounted_value(discount__discounted_value)
  );

  td_update_core #(.DATA_WIDTH(DATA_WIDTH)) update (
    .clk(clk),
    .rst_n(rst_n),
    .reward(update__reward),
    .value(update__value),
    .discounted_value(update__discounted_value),
    .alpha(update__alpha),
    .td_error(update__td_error),
    .updated_value(update__updated_value)
  );

  stream_stage #(.DATA_WIDTH(DATA_WIDTH)) output_stage (
    .clk(clk),
    .rst_n(rst_n),
    .in_valid(output_stage__in_valid),
    .in_ready(output_stage__in_ready),
    .td_error_in(output_stage__td_error_in),
    .updated_value_in(output_stage__updated_value_in),
    .out_valid(output_stage__out_valid),
    .out_ready(output_stage__out_ready),
    .td_error_out(output_stage__td_error_out),
    .updated_value_out(output_stage__updated_value_out)
  );

endmodule

`timescale 1ns/1ps

module tb_top;
  reg clk;
  reg rst_n;
  reg in_valid;
  wire in_ready;
  reg signed [7:0] reward;
  reg signed [7:0] value;
  reg signed [7:0] next_value;
  reg [7:0] gamma;
  reg [7:0] alpha;
  wire out_valid;
  reg out_ready;
  wire signed [7:0] td_error;
  wire signed [7:0] updated_value;
  integer wait_cycles;
string oracle_input_path;
string oracle_expected_path;
string oracle_scenario_id;
string oracle_scenario_class;
integer oracle_transaction_count;
integer oracle_mode;
reg [42:0] oracle_input_memory [0:4095];
reg [15:0] oracle_expected_memory [0:4095];
reg [42:0] oracle_input_record;
reg [15:0] oracle_expected_record;
reg signed [7:0] oracle_held_error;
reg signed [7:0] oracle_held_value;
integer oracle_wait_count;
integer oracle_stall_index;
integer oracle_stall_cycles;

  top dut (
    .clk(clk),
    .rst_n(rst_n),
    .in_valid(in_valid),
    .in_ready(in_ready),
    .reward(reward),
    .value(value),
    .next_value(next_value),
    .gamma(gamma),
    .alpha(alpha),
    .out_valid(out_valid),
    .out_ready(out_ready),
    .td_error(td_error),
    .updated_value(updated_value)
  );

  initial begin
    clk = 1'b0;
    forever #5 clk = ~clk;
  end

  task send_update;
    input signed [7:0] reward_i;
    input signed [7:0] value_i;
    input signed [7:0] next_value_i;
    input [7:0] gamma_i;
    input [7:0] alpha_i;
    begin
      @(negedge clk);
      in_valid = 1'b1;
      reward = reward_i;
      value = value_i;
      next_value = next_value_i;
      gamma = gamma_i;
      alpha = alpha_i;
      while (!in_ready) begin
        @(negedge clk);
      end
      @(negedge clk);
      in_valid = 1'b0;
    end
  endtask

  task expect_update;
    input signed [7:0] expected_error;
    input signed [7:0] expected_value;
    begin
      wait_cycles = 0;
      while (out_valid !== 1'b1 && wait_cycles < 16) begin
        @(posedge clk);
        #1;
        wait_cycles = wait_cycles + 1;
      end
      if (out_valid !== 1'b1) begin
        $display("TEST_FAIL output did not become valid");
        $finish;
      end
      if (td_error !== expected_error || updated_value !== expected_value) begin
        $display(
          "TEST_FAIL expected td=%0d value=%0d got td=%0d value=%0d",
          expected_error,
          expected_value,
          td_error,
          updated_value
        );
        $finish;
      end
      @(negedge clk);
    end
  endtask


task run_td_oracle_scenario;
  integer oracle_item_index;
  begin
    if (oracle_transaction_count <= 0 || oracle_transaction_count > 4096) begin
      $display("ORACLE_ERROR invalid RL TD transaction count=%0d", oracle_transaction_count);
      $finish;
    end
    $readmemh(oracle_input_path, oracle_input_memory, 0, oracle_transaction_count - 1);
    $readmemh(oracle_expected_path, oracle_expected_memory, 0, oracle_transaction_count - 1);
    rst_n = 1'b0;
    in_valid = 1'b0;
    reward = 8'sd0;
    value = 8'sd0;
    next_value = 8'sd0;
    gamma = 8'd0;
    alpha = 8'd0;
    out_ready = 1'b0;
    repeat (2) @(posedge clk);
    @(negedge clk);
    rst_n = 1'b1;
    for (oracle_item_index = 0; oracle_item_index < oracle_transaction_count;
         oracle_item_index = oracle_item_index + 1) begin
      oracle_input_record = oracle_input_memory[oracle_item_index];
      oracle_expected_record = oracle_expected_memory[oracle_item_index];
      if (oracle_input_record[40]) begin
        @(negedge clk);
        rst_n = 1'b0;
        in_valid = 1'b0;
        out_ready = 1'b0;
        repeat (2) @(posedge clk);
        if (out_valid !== 1'b0) begin
          $display("SR2FPGA_MISMATCH {\"scenario_id\":\"%0s\",\"class\":\"%0s\",\"item_index\":%0d,\"field\":\"reset_out_valid\",\"expected\":0,\"actual\":\"%0b\"}",
                   oracle_scenario_id, oracle_scenario_class, oracle_item_index, out_valid);
          $display("TEST_FAIL reset did not clear output valid");
          $finish;
        end
        @(negedge clk);
        rst_n = 1'b1;
      end
      out_ready = 1'b0;
      in_valid = 1'b1;
      reward = oracle_input_record[7:0];
      value = oracle_input_record[15:8];
      next_value = oracle_input_record[23:16];
      gamma = oracle_input_record[31:24];
      alpha = oracle_input_record[39:32];
      oracle_wait_count = 0;
      while (in_ready !== 1'b1 && oracle_wait_count < 500) begin
        @(negedge clk);
        oracle_wait_count = oracle_wait_count + 1;
      end
      if (in_ready !== 1'b1) begin
        $display("SR2FPGA_MISMATCH {\"scenario_id\":\"%0s\",\"class\":\"%0s\",\"item_index\":%0d,\"field\":\"in_ready\",\"expected\":1,\"actual\":\"%0b\"}",
                 oracle_scenario_id, oracle_scenario_class, oracle_item_index, in_ready);
        $display("TEST_FAIL input timeout");
        $finish;
      end
      @(posedge clk);
      @(negedge clk);
      in_valid = 1'b0;
