        $display("SR2FPGA_MISMATCH {\"scenario_id\":\"%0s\",\"class\":\"%0s\",\"item_index\":%0d,\"expected\":{\"td_error\":%0d,\"updated_value\":%0d},\"actual\":{\"td_error\":%0d,\"updated_value\":%0d}}",
